+import java.io.File;
+import lombok.DirectoryRunner.FileTester;
+import lombok.RunTestsViaDelombok;
+import lombok.transform.TestWithDelombok;
+
+public class FieldDefaultsRegression {
+    public static void main(String[] args) throws Throwable {
+        TestWithDelombok params = new TestWithDelombok();
+        int failures = 0;
+        int tests = 0;
+        for (File file : params.getBeforeDirectory().listFiles()) {
+            if (!file.getName().startsWith("FieldDefaults")) continue;
+            FileTester tester = new RunTestsViaDelombok().createTester(params, file, "javac", params.getVersion());
+            if (tester == null) throw new AssertionError("Skipped " + file);
+            tests++;
+            try {
+                tester.runTest();
+            } catch (AssertionError failure) {
+                failures++;
+            }
+        }
+        System.out.println("FieldDefaults tests: " + tests + ", failures: " + failures);
+        if (failures != 0) throw new AssertionError("FieldDefaults regression failures: " + failures);
+    }
+}
